<script>
window.LabKit = window.LabKit || (() => {
  const NS = 'http://www.w3.org/2000/svg';
  const sum = a => a.reduce((s, v) => s + v, 0);
  const mean = a => sum(a) / a.length;
  const variance = (a, ddof = 0) => { const m = mean(a); return sum(a.map(v => (v - m) ** 2)) / (a.length - ddof); };
  const sd = (a, ddof = 0) => Math.sqrt(variance(a, ddof));
  // Percentil con interpolación lineal (convención de numpy.percentile por defecto).
  const quantile = (a, q) => {
    const s = [...a].sort((x, y) => x - y), pos = (s.length - 1) * q, lo = Math.floor(pos), hi = Math.ceil(pos);
    return s[lo] + (s[hi] - s[lo]) * (pos - lo);
  };
  const median = a => quantile(a, 0.5);
  const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));
  const fmt = (v, d = 2) => (v === null || v === undefined || Number.isNaN(v)) ? '—'
    : Number(v).toLocaleString('es-MX', { minimumFractionDigits: d, maximumFractionDigits: d });
  // Generador pseudoaleatorio reproducible (mulberry32) y normal estándar (Box-Muller).
  const rng = seed => {
    let t = seed >>> 0;
    const u = () => { t += 0x6D2B79F5; let r = Math.imul(t ^ (t >>> 15), 1 | t); r ^= r + Math.imul(r ^ (r >>> 7), 61 | r); return ((r ^ (r >>> 14)) >>> 0) / 4294967296; };
    u.normal = () => { let a = 0, b = 0; while (a === 0) a = u(); while (b === 0) b = u(); return Math.sqrt(-2 * Math.log(a)) * Math.cos(2 * Math.PI * b); };
    return u;
  };
  const niceTicks = (lo, hi, n = 5) => {
    if (hi === lo) { hi = lo + 1; }
    const raw = (hi - lo) / n, mag = 10 ** Math.floor(Math.log10(raw)), f = raw / mag;
    const step = (f >= 5 ? 10 : f >= 2 ? 5 : f >= 1 ? 2 : 1) * mag;
    const out = [];
    for (let v = Math.ceil(lo / step - 1e-9) * step; v <= hi + 1e-9; v += step) out.push(Math.abs(v) < step * 1e-9 ? 0 : v);
    return out;
  };
  const el = (tag, attrs = {}, parent) => {
    const node = document.createElementNS(NS, tag);
    for (const [k, v] of Object.entries(attrs)) if (v !== undefined && v !== null) node.setAttribute(k, v);
    if (parent) parent.appendChild(node);
    return node;
  };
  // Graficador mínimo: escala lineal, ejes, rejilla y primitivas.
  function chart(svg, opts) {
    const W = opts.width || 480, H = opts.height || 300;
    const m = Object.assign({ top: 14, right: 14, bottom: 38, left: 48 }, opts.margin || {});
    svg.setAttribute('viewBox', `0 0 ${W} ${H}`);
    svg.classList.add('plab-chart');
    svg.replaceChildren();
    const [x0, x1] = opts.x, [y0, y1] = opts.y;
    const iw = W - m.left - m.right, ih = H - m.top - m.bottom;
    const X = v => m.left + (v - x0) / (x1 - x0) * iw;
    const Y = v => m.top + ih - (v - y0) / (y1 - y0) * ih;
    const c = {
      svg, X, Y, W, H, m, iw, ih,
      invX: px => x0 + (px - m.left) / iw * (x1 - x0),
      invY: py => y0 + (m.top + ih - py) / ih * (y1 - y0),
      g: el('g', {}, svg),
      axes({ xTicks = 5, yTicks = 5, xLabel = '', yLabel = '', xFmt = v => fmt(v, Math.abs(v) < 10 && v % 1 ? 1 : 0), yFmt, grid = true, xCats } = {}) {
        const ax = el('g', {}, svg); svg.insertBefore(ax, c.g);
        const yf = yFmt || xFmt;
        if (yTicks) niceTicks(y0, y1, yTicks).forEach(t => {
          if (grid) el('line', { x1: m.left, x2: m.left + iw, y1: Y(t), y2: Y(t), class: 'grid' }, ax);
          el('text', { x: m.left - 6, y: Y(t) + 3.5, 'text-anchor': 'end' }, ax).textContent = yf(t);
        });
        if (xCats) xCats.forEach(([v, lab]) => { el('text', { x: X(v), y: m.top + ih + 16, 'text-anchor': 'middle' }, ax).textContent = lab; });
        else if (xTicks) niceTicks(x0, x1, xTicks).forEach(t => {
          if (grid) el('line', { x1: X(t), x2: X(t), y1: m.top, y2: m.top + ih, class: 'grid' }, ax);
          el('text', { x: X(t), y: m.top + ih + 16, 'text-anchor': 'middle' }, ax).textContent = xFmt(t);
        });
        el('line', { x1: m.left, x2: m.left + iw, y1: m.top + ih, y2: m.top + ih, class: 'axis' }, ax);
        el('line', { x1: m.left, x2: m.left, y1: m.top, y2: m.top + ih, class: 'axis' }, ax);
        if (xLabel) el('text', { x: m.left + iw / 2, y: H - 4, 'text-anchor': 'middle', class: 'strong' }, ax).textContent = xLabel;
        if (yLabel) el('text', { x: 12, y: m.top + ih / 2, 'text-anchor': 'middle', transform: `rotate(-90 12 ${m.top + ih / 2})`, class: 'strong' }, ax).textContent = yLabel;
        return c;
      },
      zeroLines() {
        if (x0 < 0 && x1 > 0) el('line', { x1: X(0), x2: X(0), y1: m.top, y2: m.top + ih, class: 'zero' }, c.g);
        if (y0 < 0 && y1 > 0) el('line', { x1: m.left, x2: m.left + iw, y1: Y(0), y2: Y(0), class: 'zero' }, c.g);
        return c;
      },
      path(points, cls = 's1 line') {
        const d = points.filter(p => p && Number.isFinite(p[1])).map((p, i) => `${i ? 'L' : 'M'}${X(p[0]).toFixed(1)},${Y(p[1]).toFixed(1)}`).join('');
        return el('path', { d, class: cls }, c.g);
      },
      line(xa, ya, xb, yb, cls = 's1 line') { return el('line', { x1: X(xa), y1: Y(ya), x2: X(xb), y2: Y(yb), class: cls }, c.g); },
      dot(x, y, r = 5, cls = 's1 dot') { return el('circle', { cx: X(x), cy: Y(y), r, class: cls }, c.g); },
      rect(xa, ya, xb, yb, cls = 's1 soft') {
        return el('rect', { x: Math.min(X(xa), X(xb)), y: Math.min(Y(ya), Y(yb)), width: Math.abs(X(xb) - X(xa)), height: Math.abs(Y(yb) - Y(ya)), class: cls }, c.g);
      },
      text(x, y, s, attrs = {}) { const t = el('text', Object.assign({ x: X(x), y: Y(y) }, attrs), c.g); t.textContent = s; return t; },
      arrow(xa, ya, xb, yb, cls = 's1') {
        const ax = X(xa), ay = Y(ya), bx = X(xb), by = Y(yb), ang = Math.atan2(by - ay, bx - ax), h = 8;
        el('line', { x1: ax, y1: ay, x2: bx, y2: by, class: cls + ' line' }, c.g);
        el('path', { d: `M${bx},${by}L${bx - h * Math.cos(ang - 0.4)},${by - h * Math.sin(ang - 0.4)}L${bx - h * Math.cos(ang + 0.4)},${by - h * Math.sin(ang + 0.4)}Z`, class: cls }, c.g);
      },
      // Convierte un evento de puntero a coordenadas de datos.
      pointer(evt) {
        const pt = svg.createSVGPoint(); pt.x = evt.clientX; pt.y = evt.clientY;
        const p = pt.matrixTransform(svg.getScreenCTM().inverse());
        return [c.invX(p.x), c.invY(p.y)];
      }
    };
    svg.__chart = c;
    return c;
  }
  // Botones segmentados: devuelve un getter del valor activo.
  function segmented(container, onChange) {
    const buttons = [...container.querySelectorAll('button')];
    let value = (buttons.find(b => b.getAttribute('aria-pressed') === 'true') || buttons[0]).dataset.value;
    const set = v => { value = v; buttons.forEach(b => b.setAttribute('aria-pressed', String(b.dataset.value === v))); };
    set(value);
    buttons.forEach(b => b.addEventListener('click', () => { set(b.dataset.value); onChange && onChange(value); }));
    return { get: () => value, set: v => { set(v); onChange && onChange(value); } };
  }
  return { sum, mean, variance, sd, quantile, median, clamp, fmt, rng, niceTicks, el, chart, segmented };
})();
</script>
```
:::


Preprocesar datos es convertir registros capturados para operar un negocio en entradas coherentes para una pregunta analítica. Antes de transformar una columna, preguntamos qué representa, cómo se obtuvo y qué información estará disponible cuando se use el modelo. La limpieza ayuda a evitar errores conocidos; no garantiza buenas predicciones.

En BigMart, `LF` y `Low Fat` pueden significar lo mismo, un peso negativo requiere revisión y un precio extraordinario podría ser un error o un producto especial. Una regla automática no puede decidir lo último sin contexto. Tampoco todos los modelos necesitan el mismo tratamiento: algunos aceptan valores ausentes o categorías directamente, mientras que otros requieren imputación o codificación.[^modelos]

::: {.callout-note title="Antes de limpiar"}
Conserva una copia del valor original y registra la regla aplicada. Convierte en ausente un valor imposible según una regla de negocio documentada; investiga un valor atípico plausible antes de eliminarlo.
:::

## Ejemplo: de una tabla cruda a variables utilizables

Esta muestra **inventada para aprender** contiene problemas de completitud, validez y consistencia. Los límites de peso y precio que usaremos son supuestos del ejercicio, no reglas generales de BigMart.

| Producto | `Item_Weight` | `Item_MRP` | `Outlet_Establishment_Year` | `Item_Fat_Content` |
|---|---:|---:|---|---|
| FDA15 | 9.30 | 249.80 | 1999 | Low Fat |
| DRC01 | -5.00 | 0.00 | 09-Jan-2009 | low fat |
| FDN15 | NA | 1200000.00 | 1998 | LF |
| FDX07 | 19.20 | NA | 14/02/1998 | Regular |
| NCD19 | 200.00 | 53.86 | 1985-01-20 | reg |

El orden de trabajo es: definir qué valores violan reglas del dominio; unificar etiquetas y formatos; separar entrenamiento y prueba; **ajustar** las estadísticas y categorías con entrenamiento; **aplicar** esas mismas transformaciones a ambos conjuntos. El identificador del producto no es una medida continua: aquí lo conservamos para auditoría, pero no lo enviamos al modelo.

### Una transformación a mano

Consideremos tres pesos de entrenamiento: $10$, ausente y $20$. Si elegimos imputación por media, calculamos $(10+20)/2=15$ con los dos pesos observados. La columna resultante es $(10,15,20)$. Su media es $15$ y su desviación estándar poblacional[^desv] es $\sqrt{\tfrac{(10-15)^2+(15-15)^2+(20-15)^2}{3}}=\sqrt{50/3}\approx4.082$. Al estandarizarla obtenemos $\big(\tfrac{10-15}{4.082},\,0,\,\tfrac{20-15}{4.082}\big)\approx(-1.225,0,1.225)$.

Ahora llega un producto nuevo de prueba con peso $40$. Si por descuido «ajustamos» con las cuatro filas, la media de imputación pasa a $(10+20+40)/3\approx23.33$: el valor que asignamos a una fila **de entrenamiento** depende de un dato que no deberíamos haber visto. Esta es la idea de fuga que formalizaremos enseguida y que el laboratorio permite manipular.

Si las categorías son `Low Fat`, `LF` y `Regular`, primero unificamos `LF` con `Low Fat`. Después, una codificación *one hot*[^onehot] da las columnas `Fat_Low` y `Fat_Regular`:

| Peso estandarizado | `Fat_Low` | `Fat_Regular` |
|---:|---:|---:|
| -1.225 | 1 | 0 |
| 0 | 1 | 0 |
| 1.225 | 0 | 1 |

Esta matriz solo ilustra un posible preprocesador. El escalado es útil para muchos modelos sensibles a magnitudes o distancias, pero no es un requisito universal.[^escalado]

## Formalización: reglas, parámetros y calidad

Un pipeline es una composición[^composicion] ordenada $T=T_k\circ\cdots\circ T_1$. Algunas etapas aplican reglas establecidas por el dominio; otras aprenden parámetros[^parametro] $\theta$ a partir de datos. Para evaluar un modelo, ajustamos $\hat\theta=\operatorname{fit}(X_{\mathrm{train}})$ y usamos el mismo estado en $T_{\hat\theta}(X_{\mathrm{train}})$ y $T_{\hat\theta}(X_{\mathrm{test}})$. Ajustar con $X_{\mathrm{test}}$ incorpora información de evaluación al entrenamiento, una forma de *fuga de datos*.[^fuga]

Un preprocesador suele combinar comprobaciones de calidad distintas:

| Dimensión | Pregunta práctica | Ejemplo de control |
|---|---|---|
| Completitud | ¿Faltan valores requeridos? | Proporción de `Item_Weight` ausente |
| Validez | ¿Respeta tipos y rangos acordados? | Peso positivo dentro de un rango de negocio |
| Consistencia | ¿Coinciden representaciones equivalentes? | `LF` y `Low Fat` |
| Unicidad | ¿Hay registros duplicados de una entidad? | Producto y tienda repetidos sin justificación |
| Exactitud | ¿Se aproxima el registro a la realidad? | Contrastar un precio con la fuente original |
| Oportunidad | ¿Llegó a tiempo para la decisión? | Retraso entre venta y captura |

Para una columna requerida, una medida simple de completitud es $C=1-\frac{n_{\mathrm{ausentes}}}{n}$. Las demás dimensiones necesitan reglas y fuentes de referencia propias; una sola puntuación no las resume.

::: {.callout-tip title="Práctica en equipos de datos"}
Documenta el esquema y las reglas de calidad que afectan al modelo, valida los lotes nuevos y observa cómo cambian faltantes, rangos y categorías con el tiempo. Una alerta debe conducir a investigar la causa; una variación de distribución por sí sola no demuestra pérdida de rendimiento.[^drift]
:::

## Laboratorio: ¿qué cambia si ajustamos con datos de prueba?

**Objetivo.** Identificar qué estadísticas pertenecen al entrenamiento y observar cómo se altera una imputación cuando se usan datos de prueba para calcularlas.

**Hipótesis.** Con pesos observados de entrenamiento $10$ y $20$, la media para imputar debe ser $15$. Si se incorpora el peso $40$ de prueba al ajuste, la media cambia.

**Pasos.** Con «Imputar peso» activo, compara ambos modos de ajuste y observa cómo se mueve la línea naranja. Activa «Estandarizar precio» y anota μ y σ en cada modo. Por último, activa «Codificar tienda»: la fila de prueba pertenece a una tienda *Hypermarket* que no aparece en entrenamiento. ¿Qué columnas existen en cada modo y cuál de las dos matrices podría producirse realmente en producción?

